const box = { value: 1 };
box.value = 2;
box.value += 3;
const doubled = [1, 2].map((v) => v * 2).filter((v) => v > 2);
const { p, q: [r1, r2] } = { p: 1, q: [2, 3] };
const [head, ...tail] = [4, 5, 6];
let total = 0;
for (const [index, value] of [[0, 10], [1, 20]]) {
  total = total + index + value;
}
console.log(box.value, doubled, p, r1, r2, head, tail, total);
